  const handleAddCustomDay = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!canEditSchedule) return;
    try {
      const nextIdx = masterPlan.length + 1;
      const defaultDate = new Date();
      defaultDate.setDate(defaultDate.getDate() + (nextIdx - 1));
      const finalDate = newDayForm.date || defaultDate.toISOString().split('T')[0];
      
      const dObj = new Date(finalDate + 'T00:00:00');
      const dayNameAuto = !isNaN(dObj.getTime()) ? dObj.toLocaleDateString('id-ID', { weekday: 'long' }) : '';
      const finalName = (newDayForm.name || '').trim() || (dayNameAuto ? `Hari ${nextIdx} (${dayNameAuto})` : `Hari ${nextIdx}`);
      
      const count = newDayForm.sessionCount || 3;
      const defaultTimeSlots = [
        { start: '07:30', end: '09:00' },
        { start: '09:30', end: '11:00' },
        { start: '11:30', end: '13:00' },
        { start: '13:30', end: '15:00' },
        { start: '15:30', end: '17:00' }
      ];

      const initialSessions = [];
      for (let i = 0; i < count; i++) {
        const slot = defaultTimeSlots[i] || { start: '07:30', end: '09:00' };
        initialSessions.push({
          id: `sess-${Date.now()}-${i}`,
          name: `Sesi ${i + 1}`,
          startTime: slot.start,
          endTime: slot.end,
          subjectId: '',
          subjectName: '',
          classes: [],
          roomName: rooms[0]?.name || '',
          supervisorEmail: '',
          supervisorName: ''
        });
      }

      const tempId = `temp-day-${Date.now()}`;
      const optimisticDay = {
        id: tempId,
        name: finalName,
        date: finalDate,
        sessions: initialSessions,
        createdAt: Timestamp.now()
      };

      // Optimistic update: instantly appear in UI and close modal
      setMasterPlan(prev => [...prev, optimisticDay].sort((a: any, b: any) => (a.date || '').localeCompare(b.date || '')));
      setShowAddDayModal(false);
      setNewDayForm({ name: '', date: '', sessionCount: 3 });

      addDoc(collection(db, 'master_plan'), {
        name: finalName,
        date: finalDate,
        sessions: initialSessions,
        createdAt: serverTimestamp()
      }).then(docRef => {
        setMasterPlan(prev => dedupeById(prev.map(d => d.id === tempId ? { ...d, id: docRef.id } : d)));
      }).catch(err => {
        console.error("Error adding custom day:", err);
        setMasterPlan(prev => prev.filter(d => d.id !== tempId));
        alert("Gagal menambahkan hari ujian.");
      });
    } catch (err) {
      console.error("Error adding custom day:", err);
      alert("Gagal menambahkan hari ujian.");
    }
  };

  const handleAddMasterDay = async () => {
    if (!canEditSchedule) return;
    const nextIdx = masterPlan.length + 1;
    const defaultDate = new Date();
    defaultDate.setDate(defaultDate.getDate() + (nextIdx - 1));
    setNewDayForm({
      name: `Hari ${nextIdx}`,
      date: defaultDate.toISOString().split('T')[0],
      sessionCount: 3
    });
    setShowAddDayModal(true);
  };

  // --- TWO-WAY SCHEDULE <-> EXAM TIME SYNCHRONIZATION HELPERS ---
  const formatDateForDatetimeLocal = (val: any): string => {
    if (!val) return '';
    const d = val?.toDate ? val.toDate() : new Date(val);
    if (isNaN(d.getTime())) return '';
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const hrs = String(d.getHours()).padStart(2, '0');
    const mins = String(d.getMinutes()).padStart(2, '0');
    return `${y}-${m}-${day}T${hrs}:${mins}`;
  };

  const extractLocalDateAndTime = (val: any): { dateStr: string; timeStr: string } => {
    if (!val) return { dateStr: '', timeStr: '' };
    const d = val?.toDate ? val.toDate() : new Date(val);
    if (isNaN(d.getTime())) return { dateStr: '', timeStr: '' };
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const hrs = String(d.getHours()).padStart(2, '0');
    const mins = String(d.getMinutes()).padStart(2, '0');
    return { dateStr: `${y}-${m}-${day}`, timeStr: `${hrs}:${mins}` };
  };

  const getExamTimestampMs = (val: any): number => {
    if (!val) return 0;
    if (typeof val?.toMillis === 'function') return val.toMillis();
    if (typeof val?.toDate === 'function') return val.toDate().getTime();
    const d = new Date(val);
    return isNaN(d.getTime()) ? 0 : d.getTime();
  };

  const getFormPreviewEmbedData = (rawLink?: string) => {
    const decrypted = decryptLink(rawLink || '').trim();
    if (!decrypted || decrypted === 'Belum diatur / Not set' || decrypted === 'Belum diatur') {
      return { cleanUrl: '', embedUrl: '', isShortened: false, isValid: false };
    }
    let cleanUrl = decrypted;
    if (!cleanUrl.startsWith('http://') && !cleanUrl.startsWith('https://')) {
      cleanUrl = 'https://' + cleanUrl;
    }
    let embedUrl = cleanUrl;
    const isShortened = embedUrl.includes('forms.gle/');
    if (embedUrl.includes('docs.google.com/forms')) {
      if (embedUrl.includes('/edit')) {
        embedUrl = embedUrl.replace(/\/edit.*$/, '/viewform');
      }
      if (!embedUrl.includes('embedded=true')) {
        embedUrl = embedUrl.includes('?') ? `${embedUrl}&embedded=true` : `${embedUrl}?embedded=true`;
      }
    }
    return { cleanUrl, embedUrl, isShortened, isValid: true };
  };

  const openExamFormPreview = (exam: any) => {
    setPreviewExamModal(exam);
    setPreviewIframeKey(prev => prev + 1);
  };

  const combineDateAndTimeToTimestamp = (dateStr: string, timeStr: string): Timestamp | null => {
    if (!dateStr || !timeStr) return null;
    const [y, m, d] = dateStr.split('-').map(Number);
    const [hrs, mins] = timeStr.split(':').map(Number);
    if (!y || !m || !d) return null;
    const dt = new Date(y, m - 1, d, hrs || 0, mins || 0, 0, 0);
    if (isNaN(dt.getTime())) return null;
    return Timestamp.fromDate(dt);
  };

  const getSessionGradeRows = (session: any): string[] => {
    if (Array.isArray(session?.activeGrades) && session.activeGrades.length > 0) {
      return session.activeGrades;
    }
    return ['Kelas VII', 'Kelas VIII', 'Kelas IX'];
  };

  const getGradeRowBadgeStyle = (gradeKey: string): string => {
    const k = String(gradeKey || '').trim();
    if (k === 'Kelas VII') return 'bg-blue-50 text-blue-700 border-blue-200';
    if (k === 'Kelas VIII') return 'bg-indigo-50 text-indigo-700 border-indigo-200';
    if (k === 'Kelas IX') return 'bg-purple-50 text-purple-700 border-purple-200';
    if (k.includes('&') || k.includes(',') || k.toLowerCase().includes('semua') || k.toLowerCase().includes('gabung')) {
      return 'bg-emerald-50 text-emerald-700 border-emerald-200';
    }
    return 'bg-amber-50 text-amber-800 border-amber-200';
  };

  const doesStudentMatchGradeRow = (studentClassRaw: string, gradeKey: string): boolean => {
    const sc = String(studentClassRaw || '').toLowerCase().trim();
    const gk = String(gradeKey || '').toLowerCase().trim();
    if (!sc || !gk) return false;
    if (gk === 'semua kelas' || gk === 'semua jenjang') return true;

    const studentGrade = getGradeLevelFromClass(studentClassRaw); // 'Kelas VII' | 'Kelas VIII' | 'Kelas IX' | null
    if (studentGrade) {
      if (studentGrade === 'Kelas VII' && /\b(vii|7)\b/i.test(gk)) return true;
      if (studentGrade === 'Kelas VIII' && /\b(viii|8)\b/i.test(gk)) return true;
      if (studentGrade === 'Kelas IX' && /\b(ix|9)\b/i.test(gk)) return true;
    }
    return gk.includes(sc) || sc.includes(gk);
  };

  const formatRoomSupervisorDisplayName = (rs: any): string => {
    const sup1 = (rs?.supervisorName || rs?.supervisorEmail || '').trim();
    const sup2 = (rs?.supervisor2Name || rs?.supervisor2Email || '').trim();
    if (sup1 && sup2) return `${sup1} & ${sup2}`;
    return sup1 || sup2 || '';
  };

  const isRoomSupervisorAssigned = (rs: any): boolean => {
    return Boolean(
      (rs?.supervisorEmail || '').trim() ||
      (rs?.supervisorName || '').trim() ||
      (rs?.supervisor2Email || '').trim() ||
      (rs?.supervisor2Name || '').trim()
    );
  };

  const isSupervisorMatchingRoomRow = (rs: any, targetEmail?: string, targetName?: string): boolean => {
    const em = String(targetEmail || '').toLowerCase().trim();
    const nm = String(targetName || '').toLowerCase().trim();
    const rEm1 = String(rs?.supervisorEmail || '').toLowerCase().trim();
    const rEm2 = String(rs?.supervisor2Email || '').toLowerCase().trim();
    const rNm1 = String(rs?.supervisorName || '').toLowerCase().trim();
    const rNm2 = String(rs?.supervisor2Name || '').toLowerCase().trim();
    if (em && (rEm1 === em || rEm2 === em)) return true;
    if (nm && nm.length > 2) {
      if (rNm1 === nm || rNm2 === nm) return true;
      if (rNm1 && rNm1.length > 3 && (rNm1.includes(nm) || nm.includes(rNm1))) return true;
      if (rNm2 && rNm2.length > 3 && (rNm2.includes(nm) || nm.includes(rNm2))) return true;
    }
    return false;
  };

  const broadcastMasterPlanUpdate = useCallback((nextPlan: any[]) => {
    try {
      localStorage.setItem('cached_dashboard_masterPlan', JSON.stringify(nextPlan));
      if (typeof BroadcastChannel !== 'undefined') {
        const bc = new BroadcastChannel('smpn2_token_sync_channel');
        bc.postMessage({ type: 'MASTER_PLAN_UPDATED', masterPlan: nextPlan });
        bc.close();
      }
    } catch (e) {}
  }, []);

  const detectTargetGradesForExam = (examObj: any): string[] => {
    const titleLower = String(examObj?.title || '').toLowerCase();
    const assignClasses = (examObj?.assignments || []).map((a: any) => String(a?.classroomId || '').toLowerCase());
    const combinedText = [titleLower, ...assignClasses].join(' ');

    const matched: string[] = [];
    if (/\b(kelas\s*7|kelas\s*vii|7\s*[a-z]|vii)\b/i.test(combinedText)) matched.push('Kelas VII');
    if (/\b(kelas\s*8|kelas\s*viii|8\s*[a-z]|viii)\b/i.test(combinedText)) matched.push('Kelas VIII');
    if (/\b(kelas\s*9|kelas\s*ix|9\s*[a-z]|ix)\b/i.test(combinedText)) matched.push('Kelas IX');

    return matched.length > 0 ? matched : ['Kelas VII', 'Kelas VIII', 'Kelas IX'];
  };

  const findLinkedExamForGradeCell = (gradeKey: string, gradeData: any, session: any): any | null => {
    const explicitExamId = gradeData?.examId || (!gradeData?.subjectId ? session?.examId : '');
    if (explicitExamId) {
      const byId = exams.find(e => e.id === explicitExamId);
      if (byId) return byId;
    }
    const gSubjectId = gradeData?.subjectId !== undefined ? gradeData.subjectId : (session?.subjectId || '');
    if (!gSubjectId) return null;

    const candidates = exams.filter(e => e.subjectId === gSubjectId);
    if (candidates.length === 0) return null;
    if (candidates.length === 1) return candidates[0];

    const byGrade = candidates.find(e => detectTargetGradesForExam(e).includes(gradeKey));
    return byGrade || candidates[0];
  };

  // Daftar tugas mengawas yang disinkronkan langsung dari tabel `masterPlan` (mendukung Pengawas 1, Pengawas 2, dan Simulasi Pengawas)
  const mySupervisorDutyItems = useMemo(() => {
    const targetEmail = (effectiveSupervisorEmail || '').toLowerCase().trim();
    const targetName = (effectiveSupervisorName || '').trim();
    if (!targetEmail && !targetName) return [];

    const now = new Date();
    const todayIso = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
    const items: {
      id: string;
      dayId: string;
      dayName: string;
      dayDate: string;
      formattedDate: string;
      isToday: boolean;
      sessionIndex: number;
      sessionName: string;
      roomName: string;
      gradesLabel: string;
      subjectNames: string;
      examTitles: string;
      startTime: string;
      endTime: string;
      positionLabel: string;
      partnerName: string;
    }[] = [];

    (masterPlan || []).forEach((day: any, dayIdx: number) => {
      const dateRaw = String(day?.date || '').trim();
      const dObj = new Date(dateRaw + 'T00:00:00');
      const formattedDate = !isNaN(dObj.getTime())
        ? dObj.toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })
        : dateRaw || `Hari ${dayIdx + 1}`;
      const isToday = dateRaw === todayIso;
      const dayName = day?.name || `Hari ${dayIdx + 1}`;

      (day?.sessions || []).forEach((session: any, sIdx: number) => {
        const gradeKeys = getSessionGradeRows(session);
        const roomSups: any[] = Array.isArray(session?.roomSupervisors) ? session.roomSupervisors : [];

        const matchedRooms = roomSups.filter((rs: any) =>
          isSupervisorMatchingRoomRow(rs, targetEmail, targetName)
        );

        if (matchedRooms.length > 0) {
          matchedRooms.forEach((rs: any, rIdx: number) => {
            const applicableGrades = gradeKeys.filter(
              (gk) => !rs.className || rs.className === 'Semua Kelas' || rs.className === gk
            );
            const activeGradesList = applicableGrades.length > 0 ? applicableGrades : gradeKeys;

            const subjSet = new Set<string>();
            const examSet = new Set<string>();
            let firstStart = '';
            let lastEnd = '';

            activeGradesList.forEach((gk) => {
              const gData = session.gradesData?.[gk] || {};
              const st = gData.startTime !== undefined ? gData.startTime : (session.startTime || '07:30');
              const et = gData.endTime !== undefined ? gData.endTime : (session.endTime || '09:00');
              if (!firstStart) firstStart = st;
              lastEnd = et;

              const subId = gData.subjectId !== undefined ? gData.subjectId : (session.subjectId || '');
              const subName =
                gData.subjectName ||
                subjects.find((s: any) => s.id === subId)?.name ||
                session.subjectName ||
                '';
              if (subName) subjSet.add(subName);

              const linkedEx = findLinkedExamForGradeCell(gk, gData, session);
              if (linkedEx?.title) {
                examSet.add(linkedEx.title);
              } else if (gData.examTitle) {
                examSet.add(gData.examTitle);
              }
            });

            const rEm1 = String(rs?.supervisorEmail || '').toLowerCase().trim();
            const rNm1 = String(rs?.supervisorName || '').toLowerCase().trim();
            const nmLower = targetName.toLowerCase();
            const isSup1 =
              (targetEmail && rEm1 === targetEmail) ||
              (nmLower.length > 2 && (rNm1 === nmLower || (rNm1.length > 3 && (rNm1.includes(nmLower) || nmLower.includes(rNm1)))));

            const sup1Display = (rs?.supervisorName || rs?.supervisorEmail || '').trim();
            const sup2Display = (rs?.supervisor2Name || rs?.supervisor2Email || '').trim();
            const positionLabel = isSup1 ? 'Pengawas 1' : 'Pengawas 2';
            const partnerName = isSup1 ? sup2Display : sup1Display;

            items.push({
              id: `${day.id}_${sIdx}_${rs.id || rs.roomName || rIdx}`,
              dayId: day.id,
              dayName,
              dayDate: dateRaw,
              formattedDate,
              isToday,
              sessionIndex: sIdx,
              sessionName: session.name || `Sesi ${sIdx + 1}`,
              roomName: rs.roomName || 'Ruang Ujian',
              gradesLabel:
                rs.className && rs.className !== 'Semua Kelas'
                  ? rs.className
                  : activeGradesList.join(', '),
              subjectNames: Array.from(subjSet).join(', ') || 'Mata Pelajaran Ujian',
              examTitles: Array.from(examSet).join(', '),
              startTime: firstStart || session.startTime || '07:30',
              endTime: lastEnd || session.endTime || '09:00',
              positionLabel,
              partnerName,
            });
          });
        } else {
          // Fallback jika pengawas diatur langsung di level sesi
          const sessEm = String(session?.supervisorEmail || '').toLowerCase().trim();
          const sessNm = String(session?.supervisorName || '').toLowerCase().trim();
          const nmLower = targetName.toLowerCase();
          const isSessionMatch =
            (targetEmail && sessEm === targetEmail) ||
            (nmLower.length > 2 && sessNm === nmLower);

          if (isSessionMatch) {
            const subName =
              session.subjectName ||
              subjects.find((s: any) => s.id === session.subjectId)?.name ||
              'Mata Pelajaran Ujian';
            items.push({
              id: `${day.id}_${sIdx}_session`,
              dayId: day.id,
              dayName,
              dayDate: dateRaw,
              formattedDate,
              isToday,
              sessionIndex: sIdx,
              sessionName: session.name || `Sesi ${sIdx + 1}`,
              roomName: session.roomName || 'Semua Ruang',
              gradesLabel: gradeKeys.join(', '),
              subjectNames: subName,
              examTitles: '',
              startTime: session.startTime || '07:30',
              endTime: session.endTime || '09:00',
              positionLabel: 'Pengawas Ruang',
              partnerName: '',
            });
          }
        }
      });
    });

    // Fallback tambahan dari koleksi `schedules` lama bila `masterPlan` belum memuatnya
    if (items.length === 0 && schedules.length > 0) {
      schedules
        .filter((s: any) => {
          const sEm = String(s.supervisorEmail || '').toLowerCase().trim();
          const sNm = String(s.supervisorName || '').toLowerCase().trim();
          return (
            (targetEmail && sEm === targetEmail) ||
            (targetName.length > 2 && sNm === targetName.toLowerCase())
          );
        })
        .forEach((s: any, idx: number) => {
          const dt = s.startTime?.toDate ? s.startTime.toDate() : null;
          const timeStr = dt
            ? dt.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })
            : '07:30';
          const dateFormatted = dt
            ? dt.toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })
            : 'Jadwal Terdaftar';
          items.push({
            id: s.id || `sched_${idx}`,
            dayId: s.masterPlanId || '',
            dayName: 'Hari Ujian',
            dayDate: '',
            formattedDate: dateFormatted,
            isToday: false,
            sessionIndex: s.sessionIndex ?? 0,
            sessionName: s.examTitle || 'Sesi Ujian',
            roomName: s.roomName || 'Ruang Ujian',
            gradesLabel: s.className || 'Semua Kelas',
            subjectNames: s.subjectName || s.examTitle || 'Ujian',
            examTitles: s.examTitle || '',
            startTime: timeStr,
            endTime: '',
            positionLabel: 'Pengawas Ruang',
            partnerName: '',
          });
        });
    }

    return items;
  }, [masterPlan, schedules, subjects, exams, effectiveSupervisorEmail, effectiveSupervisorName]);

  // Sync Exam -> Master Plan & Schedules (Called when adding or updating an Exam in Menu Ujian)
  const syncExamToMasterPlan = async (
    examId: string,
    examData: { title: string; subjectId: string; startTime: any; endTime: any; assignments?: any[] }
  ) => {
    try {
      const { dateStr, timeStr: startTimeStr } = extractLocalDateAndTime(examData.startTime);
      const { timeStr: endTimeStr } = extractLocalDateAndTime(examData.endTime);
      if (!dateStr || !startTimeStr) return;
      const finalEndTimeStr = endTimeStr || '09:00';
      const subjectName = subjects.find(s => s.id === examData.subjectId)?.name || '';
      const targetGrades = detectTargetGradesForExam(examData);

      // 1. Check if this exam is already linked in any day/session of masterPlan
      let foundExistingDay: any = null;
      let foundMatchingGradeSlots: { sIdx: number; gradeKeys: string[] }[] = [];

      for (const day of masterPlan) {
        const slotMatches: { sIdx: number; gradeKeys: string[] }[] = [];
        (day.sessions || []).forEach((sess: any, sIdx: number) => {
          const gData = sess.gradesData || {};
          const matchedGrades: string[] = [];
          ['Kelas VII', 'Kelas VIII', 'Kelas IX'].forEach((gk) => {
            const cell = gData[gk];
            if (cell?.examId === examId) {
              matchedGrades.push(gk);
            } else if (!cell?.examId && examData.subjectId && cell?.subjectId === examData.subjectId && targetGrades.includes(gk)) {
              matchedGrades.push(gk);
            }
          });
          if (matchedGrades.length === 0 && (sess.examId === examId || (!sess.examId && examData.subjectId && sess.subjectId === examData.subjectId))) {
            matchedGrades.push(...targetGrades);
          }
          if (matchedGrades.length > 0) {
            slotMatches.push({ sIdx, gradeKeys: matchedGrades });
          }
        });

        if (slotMatches.length > 0) {
          foundExistingDay = day;
          foundMatchingGradeSlots = slotMatches;
          break;
        }
      }

      if (foundExistingDay) {
        // Check if the day ONLY has this exam or if date remained the same
        const otherExamsInSameDay = (foundExistingDay.sessions || []).some((sess: any) => {
          const gData = sess.gradesData || {};
          return ['Kelas VII', 'Kelas VIII', 'Kelas IX'].some(gk => {
            const cell = gData[gk];
            if (!cell?.subjectId && !cell?.examId) return false;
            if (cell?.examId && cell.examId !== examId) return true;
            if (!cell?.examId && cell?.subjectId && cell.subjectId !== examData.subjectId) return true;
            return false;
          });
        });

        if (foundExistingDay.date === dateStr || (!otherExamsInSameDay && !masterPlan.some(d => d.id !== foundExistingDay.id && d.date === dateStr))) {
          // Update in-place on foundExistingDay (and update date if this day only had this exam)
          const updatedSessions = (foundExistingDay.sessions || []).map((sess: any, sIdx: number) => {
            const slot = foundMatchingGradeSlots.find(m => m.sIdx === sIdx);
            if (!slot) return sess;
            const nextSession = { ...sess };
            const nextGradesData = { ...(nextSession.gradesData || {}) };
            slot.gradeKeys.forEach(gk => {
              nextGradesData[gk] = {
                ...(nextGradesData[gk] || {}),
                startTime: startTimeStr,
                endTime: finalEndTimeStr,
                subjectId: examData.subjectId,
                subjectName,
                examId,
                examTitle: examData.title
              };
            });
            if (slot.gradeKeys.length === 3 || nextSession.examId === examId || nextSession.subjectId === examData.subjectId) {
              nextSession.startTime = startTimeStr;
              nextSession.endTime = finalEndTimeStr;
              nextSession.subjectId = examData.subjectId;
              nextSession.subjectName = subjectName;
              nextSession.examId = examId;
            }
            nextSession.gradesData = nextGradesData;
            return nextSession;
          });

          const updatePayload: any = { sessions: updatedSessions };
          if (foundExistingDay.date !== dateStr) {
            updatePayload.date = dateStr;
          }

          setMasterPlan(prev => prev.map(d => d.id === foundExistingDay.id ? { ...d, ...updatePayload } : d));
          await safeUpdateMasterPlanDay(foundExistingDay.id, updatePayload);
          return;
        } else {
          // Exam date moved to a different date while old day still has other exams:
          // Clear exam from old day's slots first
          const cleanedOldSessions = (foundExistingDay.sessions || []).map((sess: any, sIdx: number) => {
            const slot = foundMatchingGradeSlots.find(m => m.sIdx === sIdx);
            if (!slot) return sess;
            const nextSession = { ...sess };
            const nextGradesData = { ...(nextSession.gradesData || {}) };
            slot.gradeKeys.forEach(gk => {
              nextGradesData[gk] = {
                ...(nextGradesData[gk] || {}),
                subjectId: '',
                subjectName: '',
                examId: '',
                examTitle: ''
              };
            });
            nextSession.gradesData = nextGradesData;
            return nextSession;
          });
          setMasterPlan(prev => prev.map(d => d.id === foundExistingDay.id ? { ...d, sessions: cleanedOldSessions } : d));
          await safeUpdateMasterPlanDay(foundExistingDay.id, { sessions: cleanedOldSessions });
        }
      }

      // 2. Place into target day with `date === dateStr` (or create new day if none exists)
      const targetDay = masterPlan.find(d => d.date === dateStr);
      if (targetDay) {
        const existingSessions = [...(targetDay.sessions || [])];
        // Find a session with matching startTime or empty targetGrades
        let targetSessionIdx = existingSessions.findIndex((sess: any) => sess.startTime === startTimeStr);
        if (targetSessionIdx === -1) {
          targetSessionIdx = existingSessions.findIndex((sess: any) => {
            const gData = sess.gradesData || {};
            return targetGrades.every(gk => !gData[gk]?.subjectId && !gData[gk]?.examId) && (!sess.subjectId || sess.subjectId === examData.subjectId);
          });
        }

        if (targetSessionIdx !== -1) {
          const sess = { ...existingSessions[targetSessionIdx] };
          const gData = { ...(sess.gradesData || {}) };
          targetGrades.forEach(gk => {
            gData[gk] = {
              ...(gData[gk] || {}),
              startTime: startTimeStr,
              endTime: finalEndTimeStr,
              subjectId: examData.subjectId,
              subjectName,
              examId,
              examTitle: examData.title
            };
          });
          if (!sess.subjectId || targetGrades.length === 3) {
            sess.startTime = startTimeStr;
            sess.endTime = finalEndTimeStr;
            sess.subjectId = examData.subjectId;
            sess.subjectName = subjectName;
            sess.examId = examId;
          }
          sess.gradesData = gData;
          existingSessions[targetSessionIdx] = sess;
        } else {
          const gData: Record<string, any> = {};
          targetGrades.forEach(gk => {
            gData[gk] = {
              startTime: startTimeStr,
              endTime: finalEndTimeStr,
              subjectId: examData.subjectId,
              subjectName,
              examId,
              examTitle: examData.title
            };
          });
          existingSessions.push({
            id: `sess-${Date.now()}`,
            name: `Sesi ${existingSessions.length + 1}`,
            startTime: startTimeStr,
            endTime: finalEndTimeStr,
            subjectId: examData.subjectId,
            subjectName,
            examId,
            classes: targetGrades,
            gradesData: gData,
            roomName: rooms[0]?.name || '',
            supervisorEmail: '',
            supervisorName: ''
          });
        }

        setMasterPlan(prev => prev.map(d => d.id === targetDay.id ? { ...d, sessions: existingSessions } : d));
        await safeUpdateMasterPlanDay(targetDay.id, { sessions: existingSessions });
      } else {
        // Create a new Day in master_plan for this exam's date
        const dObj = new Date(dateStr + 'T00:00:00');
        const dayName = !isNaN(dObj.getTime()) ? dObj.toLocaleDateString('id-ID', { weekday: 'long' }) : '';
        const newDayNumber = masterPlan.length + 1;
        const gData: Record<string, any> = {};
        targetGrades.forEach(gk => {
          gData[gk] = {
            startTime: startTimeStr,
            endTime: finalEndTimeStr,
            subjectId: examData.subjectId,
            subjectName,
            examId,
            examTitle: examData.title
          };
        });
        const newSessions = [
          {
            id: `sess-${Date.now()}-1`,
            name: 'Sesi 1',
            startTime: startTimeStr,
            endTime: finalEndTimeStr,
            subjectId: examData.subjectId,
            subjectName,
            examId,
            classes: targetGrades,
            gradesData: gData,
            roomName: rooms[0]?.name || '',
            supervisorEmail: '',
            supervisorName: ''
          }
        ];
        const newDayPayload = {
          name: dayName ? `Hari ${newDayNumber} (${dayName})` : `Hari ${newDayNumber}`,
          date: dateStr,
          sessions: newSessions,
          createdAt: serverTimestamp()
        };
        const newDayRef = doc(collection(db, 'master_plan'));
        setMasterPlan(prev => dedupeById([...prev, { id: newDayRef.id, ...newDayPayload }]).sort((a: any, b: any) => (a.date || '').localeCompare(b.date || '')));
        await withFirestoreTimeout(setDoc(newDayRef, newDayPayload), 2800);
      }
    } catch (err) {
      console.warn("Notice syncing exam to master_plan:", err);
    }
  };

  const handleUpdateMasterDay = async (id: string, data: any) => {
    if (!canEditSchedule) return;
    try {
      const currentDayObj = masterPlan.find(d => d.id === id);
      setMasterPlan(prev => prev.map(d => d.id === id ? { ...d, ...data } : d));
      await safeUpdateMasterPlanDay(id, data);

      // If the Day's date changed, automatically sync all linked Exams in Menu Ujian to the new date!
      if (data.date && currentDayObj) {
        const examUpdatesMap = new Map<string, { startTs: Timestamp; endTs: Timestamp }>();
        (currentDayObj.sessions || []).forEach((sess: any) => {
          const gData = sess.gradesData || {};
          ['Kelas VII', 'Kelas VIII', 'Kelas IX'].forEach((gk) => {
            const cell = gData[gk] || {};
            const linkedExam = findLinkedExamForGradeCell(gk, cell, sess);
            if (linkedExam) {
              const sTime = cell.startTime || sess.startTime || '07:30';
              const eTime = cell.endTime || sess.endTime || '09:00';
              const startTs = combineDateAndTimeToTimestamp(data.date, sTime);
              const endTs = combineDateAndTimeToTimestamp(data.date, eTime);
              if (startTs && endTs) {
                examUpdatesMap.set(linkedExam.id, { startTs, endTs });
              }
            }
          });
        });

        if (examUpdatesMap.size > 0) {
          setExams(prev => prev.map(ex => {
            const upd = examUpdatesMap.get(ex.id);
            return upd ? { ...ex, startTime: upd.startTs, endTime: upd.endTs } : ex;
          }));
          await Promise.all(
            Array.from(examUpdatesMap.entries()).map(([exId, upd]) =>
              updateDoc(doc(db, 'exams', exId), {
                startTime: upd.startTs,
                endTime: upd.endTs
              }).catch(() => {})
            )
          );
          showToast(`Tanggal pada ${examUpdatesMap.size} ujian di Menu Ujian otomatis disinkronkan.`, 'info');
        }
      }
      
      // Sync with schedules
      const relatedSchedules = schedules.filter(s => s.masterPlanId === id);
      if (relatedSchedules.length > 0) {
        const batch = writeBatch(db);
        relatedSchedules.forEach(s => {
          const session = data.sessions ? data.sessions[s.sessionIndex] : null;
          const updateData: any = {};
          
          if (data.date) {
            const oldDate = s.startTime?.toDate ? s.startTime.toDate() : new Date();
            const [year, month, day] = data.date.split('-').map(Number);
            oldDate.setFullYear(year, month - 1, day);
            updateData.startTime = Timestamp.fromDate(oldDate);
          }
          
          if (session) {
            if (session.startTime) {
              const [hours, minutes] = session.startTime.split(':').map(Number);
              const date = updateData.startTime ? updateData.startTime.toDate() : (s.startTime?.toDate ? s.startTime.toDate() : new Date());
              date.setHours(hours || 0, minutes || 0, 0, 0);
              updateData.startTime = Timestamp.fromDate(date);
            }
            if (session.subjectId) {
              const subject = subjects.find(sub => sub.id === session.subjectId);
              updateData.subjectId = session.subjectId;
              updateData.subjectName = subject?.name || '';
            }
            if (session.name) {
              updateData.examTitle = session.name;
            }
            if (session.roomName) {
              updateData.roomName = session.roomName;
            }
            if (session.supervisorEmail) {
              updateData.supervisorEmail = session.supervisorEmail;
              updateData.supervisorName = session.supervisorName || '';
            }
            if (session.classes) {
              updateData.className = (session.classes || []).join(', ');
            }
          }
          
          if (Object.keys(updateData).length > 0) {
            batch.update(doc(db, 'schedules', s.id), updateData);
          }
        });
        await batch.commit();
      }
    } catch (error) {
      console.error("Error updating master day:", error);
    }
  };

  const confirmDeleteMasterDay = async () => {
    if (!dayToDelete) return;
    const targetId = dayToDelete.id;
    // Optimistic: instantly remove from UI
    setMasterPlan(prev => prev.filter(d => d.id !== targetId));
    setSchedules(prev => prev.filter(s => s.masterPlanId !== targetId));
    setShowDeleteDayConfirm(false);
    setDayToDelete(null);

    try {
      await deleteDoc(doc(db, 'master_plan', targetId));
      const related = schedules.filter(s => s.masterPlanId === targetId);
      if (related.length > 0) {
        const batch = writeBatch(db);
        related.forEach(s => batch.delete(doc(db, 'schedules', s.id)));
        await batch.commit();
      }
    } catch (err) {
      console.error("Error deleting day:", err);
      alert("Gagal menghapus hari ujian.");
    }
  };

  const handleDeleteMasterDay = (day: any) => {
    if (!canEditSchedule) return;
    setDayToDelete(day);
    setShowDeleteDayConfirm(true);
  };

  const handleAddSessionToDay = async (dayId: string) => {
    if (!canEditSchedule) return;
    const day = masterPlan.find(d => d.id === dayId);
    if (!day) return;
    const currentSessions = day.sessions || [];
    const nextNum = currentSessions.length + 1;
    
    let start = '07:30';
    let end = '09:00';
    if (currentSessions.length > 0) {
      const lastSession = currentSessions[currentSessions.length - 1];
      if (lastSession.endTime) {
        const [h, m] = lastSession.endTime.split(':').map(Number);
        const nextStartMin = (h || 0) * 60 + (m || 0) + 30;
        const startH = Math.floor(nextStartMin / 60) % 24;
        const startM = nextStartMin % 60;
        start = `${startH.toString().padStart(2, '0')}:${startM.toString().padStart(2, '0')}`;
        
        const nextEndMin = nextStartMin + 90;
        const endH = Math.floor(nextEndMin / 60) % 24;
        const endM = nextEndMin % 60;
        end = `${endH.toString().padStart(2, '0')}:${endM.toString().padStart(2, '0')}`;
      }
    }

    const newSession = {
      id: `sess-${Date.now()}`,
      name: `Sesi ${nextNum}`,
      startTime: start,
      endTime: end,
      subjectId: '',
      subjectName: '',
      classes: [],
      roomName: rooms[0]?.name || '',
      supervisorEmail: '',
      supervisorName: ''
    };

    const updatedSessions = [...currentSessions, newSession];
    // Optimistic: instantly show in UI
    setMasterPlan(prev => prev.map(d => d.id === dayId ? { ...d, sessions: updatedSessions } : d));

    safeUpdateMasterPlanDay(dayId, { sessions: updatedSessions });
  };

  const handleDeleteSessionFromDay = async (dayId: string, sIdx: number) => {
    if (!canEditSchedule) return;
    const day = masterPlan.find(d => d.id === dayId);
    if (!day) return;
    const session = day.sessions[sIdx];
    if (!confirm(`Hapus ${session?.name || 'Sesi ini'} dari tabel?`)) return;

    const updatedSessions = day.sessions.filter((_: any, idx: number) => idx !== sIdx);
    // Optimistic: instantly remove from UI
    setMasterPlan(prev => prev.map(d => d.id === dayId ? { ...d, sessions: updatedSessions } : d));
    setSchedules(prev => prev.filter(s => !(s.masterPlanId === dayId && s.sessionIndex === sIdx)));

    safeUpdateMasterPlanDay(dayId, { sessions: updatedSessions });

    const related = schedules.filter(s => s.masterPlanId === dayId && s.sessionIndex === sIdx);
    if (related.length > 0) {
      const batch = writeBatch(db);
      related.forEach(s => batch.delete(doc(db, 'schedules', s.id)));
      batch.commit().catch(e => console.warn("Batch delete session schedules warning:", e));
    }
  };

  const handleDuplicateSessionInDay = async (dayId: string, sIdx: number) => {
    if (!canEditSchedule) return;
    const day = masterPlan.find(d => d.id === dayId);
    if (!day) return;
    const original = day.sessions[sIdx];
    const duplicate = {
      ...original,
      id: `sess-${Date.now()}`,
      name: `${original.name || 'Sesi'} (Ruang Lain)`,
      roomName: '',
      supervisorEmail: '',
      supervisorName: ''
    };
    const updatedSessions = [...day.sessions];
    updatedSessions.splice(sIdx + 1, 0, duplicate);
    // Optimistic: instantly show duplicate
    setMasterPlan(prev => prev.map(d => d.id === dayId ? { ...d, sessions: updatedSessions } : d));

    safeUpdateMasterPlanDay(dayId, { sessions: updatedSessions });
  };

  const handleUpdateGradeCell = async (dayId: string, sIdx: number, grade: string, field: string, value: any) => {
    if (!canEditSchedule) return;
    const day = masterPlan.find(d => d.id === dayId);
    if (!day) return;
    const updatedSessions = [...day.sessions];
    const session = { ...updatedSessions[sIdx] };
    const gradesData = { ...(session.gradesData || {}) };
    const currentGrade = { ...(gradesData[grade] || {}) };

    // Ensure currentGrade has baseline times from session if not yet explicitly set
    if (currentGrade.startTime === undefined) currentGrade.startTime = session.startTime || '07:30';
    if (currentGrade.endTime === undefined) currentGrade.endTime = session.endTime || '09:00';

    if (field === 'subjectId') {
      currentGrade.subjectId = value;
      const sub = subjects.find(s => s.id === value);
      currentGrade.subjectName = sub?.name || '';
      // Auto-match with an Exam in Menu Ujian that has this subjectId
      if (value) {
        const candidates = exams.filter(e => e.subjectId === value);
        const matchedExam = candidates.find(e => detectTargetGradesForExam(e).includes(grade)) || candidates[0];
        if (matchedExam) {
          currentGrade.examId = matchedExam.id;
          currentGrade.examTitle = matchedExam.title;
        } else {
          currentGrade.examId = '';
          currentGrade.examTitle = '';
        }
      } else {
        currentGrade.examId = '';
        currentGrade.examTitle = '';
      }
    } else if (field === 'examId') {
      currentGrade.examId = value;
      const matchedExam = exams.find(e => e.id === value);
      currentGrade.examTitle = matchedExam?.title || '';
      if (matchedExam?.subjectId) {
        currentGrade.subjectId = matchedExam.subjectId;
        currentGrade.subjectName = subjects.find(s => s.id === matchedExam.subjectId)?.name || '';
      }
    } else {
      currentGrade[field] = value;
    }

    // Find linked exam to synchronize time two-way with Menu Ujian
    const linkedExam = findLinkedExamForGradeCell(grade, currentGrade, session);
    if (linkedExam) {
      currentGrade.examId = linkedExam.id;
      currentGrade.examTitle = linkedExam.title;
    }

    // Propagate default top-level session values if not yet set
    if (!session.startTime && currentGrade.startTime) session.startTime = currentGrade.startTime;
    if (!session.endTime && currentGrade.endTime) session.endTime = currentGrade.endTime;
    if (!session.subjectId && currentGrade.subjectId) {
      session.subjectId = currentGrade.subjectId;
      session.subjectName = currentGrade.subjectName;
    }

    gradesData[grade] = currentGrade;

    // If another grade in the same session is linked to the EXACT SAME examId and startTime/endTime was edited, keep them aligned
    if (linkedExam && (field === 'startTime' || field === 'endTime')) {
      getSessionGradeRows(session).forEach(otherGrade => {
        if (otherGrade === grade) return;
        const otherCell = gradesData[otherGrade];
        const otherLinked = findLinkedExamForGradeCell(otherGrade, otherCell, session);
        if (otherLinked && otherLinked.id === linkedExam.id) {
          gradesData[otherGrade] = {
            ...(otherCell || {}),
            [field]: value,
            examId: linkedExam.id,
            examTitle: linkedExam.title
          };
        }
      });
    }

    session.gradesData = gradesData;
    updatedSessions[sIdx] = session;

    // Optimistic: instantly reflect in UI & cache
    setMasterPlan(prev => {
      const next = prev.map(d => d.id === dayId ? { ...d, sessions: updatedSessions } : d);
      try { localStorage.setItem('cached_dashboard_masterPlan', JSON.stringify(next)); } catch (e) {}
      return next;
    });
    await safeUpdateMasterPlanDay(dayId, { sessions: updatedSessions });

    // TWO-WAY SYNC: Update the linked Exam's startTime & endTime in Menu Ujian (`exams` collection)
    if (linkedExam && day.date) {
      const effectiveStart = currentGrade.startTime || session.startTime || '07:30';
      const effectiveEnd = currentGrade.endTime || session.endTime || '09:00';
      const newStartTs = combineDateAndTimeToTimestamp(day.date, effectiveStart);
      const newEndTs = combineDateAndTimeToTimestamp(day.date, effectiveEnd);

      if (newStartTs && newEndTs) {
        const examUpdateData: any = {
          startTime: newStartTs,
          endTime: newEndTs
        };
        if (currentGrade.subjectId && currentGrade.subjectId !== linkedExam.subjectId) {
          examUpdateData.subjectId = currentGrade.subjectId;
        }
        setExams(prev => prev.map(ex => ex.id === linkedExam.id ? { ...ex, ...examUpdateData } : ex));
        await updateDoc(doc(db, 'exams', linkedExam.id), examUpdateData).catch(err => {
          console.error("Error syncing schedule time to exam:", err);
        });
        showToast(`Waktu ujian "${linkedExam.title}" di Menu Ujian otomatis disinkronkan (${effectiveStart} - ${effectiveEnd}).`, 'info');
      }
    }
  };

  const handleAddGradeRowToSession = async (dayId: string, sIdx: number, customGradeLabel?: string) => {
    if (!canEditSchedule) return;
    const day = masterPlan.find(d => d.id === dayId);
    if (!day) return;
    const updatedSessions = [...(day.sessions || [])];
    const session = { ...updatedSessions[sIdx] };
    const currentGrades = [...getSessionGradeRows(session)];

    const standardCandidates = ['Kelas VII', 'Kelas VIII', 'Kelas IX', 'Kelas VII & VIII', 'Kelas VIII & IX', 'Kelas VII, VIII & IX'];
    let newGrade = (customGradeLabel || '').trim();
    if (!newGrade) {
      newGrade = standardCandidates.find(c => !currentGrades.includes(c)) || `Kelas Kustom ${currentGrades.length + 1}`;
    }
    if (currentGrades.includes(newGrade)) {
      newGrade = `${newGrade} (${currentGrades.length + 1})`;
    }

    currentGrades.push(newGrade);
    const gradesData = { ...(session.gradesData || {}) };
    if (!gradesData[newGrade]) {
      gradesData[newGrade] = {
        startTime: session.startTime || '07:30',
        endTime: session.endTime || '09:00',
        subjectId: session.subjectId || '',
        subjectName: session.subjectName || ''
      };
    }

    session.activeGrades = currentGrades;
    session.gradesData = gradesData;
    updatedSessions[sIdx] = session;

    setMasterPlan(prev => {
      const next = prev.map(d => d.id === dayId ? { ...d, sessions: updatedSessions } : d);
      try { localStorage.setItem('cached_dashboard_masterPlan', JSON.stringify(next)); } catch (e) {}
      return next;
    });
    safeUpdateMasterPlanDay(dayId, { sessions: updatedSessions });
    showToast(`Baris "${newGrade}" ditambahkan ke ${session.name || `Sesi ${sIdx + 1}`}.`, 'info');
  };

  const handleDeleteGradeRowFromSession = async (dayId: string, sIdx: number, gradeIdx: number) => {
    if (!canEditSchedule) return;
    const day = masterPlan.find(d => d.id === dayId);
    if (!day) return;
    const updatedSessions = [...(day.sessions || [])];
    const session = { ...updatedSessions[sIdx] };
    const currentGrades = [...getSessionGradeRows(session)];

    if (currentGrades.length <= 1) {
      showToast('Minimal harus ada 1 baris kelas/jenjang pada setiap sesi. Jika sesi tidak dipakai, hapus sesinya.', 'error');
      return;
    }

    const removedGrade = currentGrades[gradeIdx];
    currentGrades.splice(gradeIdx, 1);
    session.activeGrades = currentGrades;
    updatedSessions[sIdx] = session;

    setMasterPlan(prev => {
      const next = prev.map(d => d.id === dayId ? { ...d, sessions: updatedSessions } : d);
      try { localStorage.setItem('cached_dashboard_masterPlan', JSON.stringify(next)); } catch (e) {}
      return next;
    });
    safeUpdateMasterPlanDay(dayId, { sessions: updatedSessions });
    showToast(`Baris "${removedGrade}" dihapus dari ${session.name || `Sesi ${sIdx + 1}`}.`, 'info');
  };

  const handleChangeGradeRowKey = async (dayId: string, sIdx: number, gradeIdx: number, newGradeKeyRaw: string) => {
    if (!canEditSchedule) return;
    const newGradeKey = (newGradeKeyRaw || '').trim();
    if (!newGradeKey) return;
    const day = masterPlan.find(d => d.id === dayId);
    if (!day) return;
    const updatedSessions = [...(day.sessions || [])];
    const session = { ...updatedSessions[sIdx] };
    const currentGrades = [...getSessionGradeRows(session)];
    const oldKey = currentGrades[gradeIdx];
    if (!oldKey || oldKey === newGradeKey) return;

    currentGrades[gradeIdx] = newGradeKey;
    const gradesData = { ...(session.gradesData || {}) };
    if (gradesData[oldKey] && !gradesData[newGradeKey]) {
      gradesData[newGradeKey] = { ...gradesData[oldKey] };
    }

    // Update roomSupervisors className references if they matched oldKey
    const updatedRoomSups = (session.roomSupervisors || []).map((rs: any) =>
      rs.className === oldKey ? { ...rs, className: newGradeKey } : rs
    );

    session.activeGrades = currentGrades;
    session.gradesData = gradesData;
    session.roomSupervisors = updatedRoomSups;
    updatedSessions[sIdx] = session;

    setMasterPlan(prev => {
      const next = prev.map(d => d.id === dayId ? { ...d, sessions: updatedSessions } : d);
      try { localStorage.setItem('cached_dashboard_masterPlan', JSON.stringify(next)); } catch (e) {}
      return next;
    });
    safeUpdateMasterPlanDay(dayId, { sessions: updatedSessions });
  };

  const handlePresetSessionGrades = async (
    dayId: string,
    sIdx: number,
    preset: 'merge_all' | 'merge_78' | 'merge_89' | 'split_all'
  ) => {
    if (!canEditSchedule) return;
    const day = masterPlan.find(d => d.id === dayId);
    if (!day) return;
    const updatedSessions = [...(day.sessions || [])];
    const session = { ...updatedSessions[sIdx] };
    const currentGrades = getSessionGradeRows(session);
    const gradesData = { ...(session.gradesData || {}) };

    // Find best existing cell data to carry over when merging
    const firstValidCell =
      currentGrades.map(k => gradesData[k]).find(c => c?.subjectId || c?.examId || c?.startTime) ||
      gradesData['Kelas VII'] ||
      gradesData['Kelas VIII'] ||
      gradesData['Kelas IX'] || {
        startTime: session.startTime || '07:30',
        endTime: session.endTime || '09:00',
        subjectId: session.subjectId || '',
        subjectName: session.subjectName || ''
      };

    let nextGrades: string[] = ['Kelas VII', 'Kelas VIII', 'Kelas IX'];
    if (preset === 'merge_all') {
      nextGrades = ['Kelas VII, VIII & IX'];
      gradesData['Kelas VII, VIII & IX'] = { ...(gradesData['Kelas VII, VIII & IX'] || firstValidCell) };
    } else if (preset === 'merge_78') {
      nextGrades = ['Kelas VII & VIII', 'Kelas IX'];
      gradesData['Kelas VII & VIII'] = {
        ...(gradesData['Kelas VII & VIII'] || gradesData['Kelas VII'] || gradesData['Kelas VIII'] || firstValidCell)
      };
      gradesData['Kelas IX'] = { ...(gradesData['Kelas IX'] || firstValidCell) };
    } else if (preset === 'merge_89') {
      nextGrades = ['Kelas VII', 'Kelas VIII & IX'];
      gradesData['Kelas VII'] = { ...(gradesData['Kelas VII'] || firstValidCell) };
      gradesData['Kelas VIII & IX'] = {
        ...(gradesData['Kelas VIII & IX'] || gradesData['Kelas VIII'] || gradesData['Kelas IX'] || firstValidCell)
      };
    } else {
      nextGrades = ['Kelas VII', 'Kelas VIII', 'Kelas IX'];
      nextGrades.forEach(gk => {
        if (!gradesData[gk]) {
          gradesData[gk] = { ...firstValidCell };
        }
      });
    }

    session.activeGrades = nextGrades;
    session.gradesData = gradesData;
    updatedSessions[sIdx] = session;

    setMasterPlan(prev => {
      const next = prev.map(d => d.id === dayId ? { ...d, sessions: updatedSessions } : d);
      try { localStorage.setItem('cached_dashboard_masterPlan', JSON.stringify(next)); } catch (e) {}
      return next;
    });
    safeUpdateMasterPlanDay(dayId, { sessions: updatedSessions });
    showToast(
      preset === 'merge_all'
        ? 'Kelas VII, VIII & IX berhasil digabung menjadi 1 baris.'
        : preset === 'split_all'
        ? 'Baris kelas dikembalikan menjadi Kelas VII, VIII, dan IX terpisah.'
        : 'Penggabungan jenjang kelas berhasil diterapkan.',
      'info'
    );
  };

