  const handleUpdateRoomSupervisorRow = async (
    dayId: string,
    sIdx: number,
    rowIdx: number,
    field:
      | 'roomName'
      | 'supervisorEmail'
      | 'supervisorName'
      | 'supervisor2Email'
      | 'supervisor2Name'
      | 'hasSecondSupervisor'
      | 'isCustomSupervisor1'
      | 'isCustomSupervisor2'
      | 'className',
    value: any
  ) => {
    if (!canEditSchedule) return;
    const day = masterPlan.find(d => d.id === dayId);
    if (!day) return;
    const session = day.sessions?.[sIdx];
    if (!session) return;
    const currentList = [...(session.roomSupervisors || [])];
    if (!currentList[rowIdx]) return;

    const currentItem = { ...currentList[rowIdx] };

    if (field === 'supervisorEmail') {
      if (value === '__CUSTOM__') {
        currentItem.isCustomSupervisor1 = true;
        currentItem.supervisorEmail = '';
      } else {
        const sup = users.find(u => u.email === value);
        currentItem.isCustomSupervisor1 = false;
        currentItem.supervisorEmail = value;
        currentItem.supervisorName = sup?.username || (value ? currentItem.supervisorName : '');
      }
    } else if (field === 'supervisorName') {
      currentItem.supervisorName = value;
      // If typed custom name doesn't match selected user, clear email or keep custom flag
      const matchedUser = users.find(
        u => (u.username || '').toLowerCase().trim() === String(value || '').toLowerCase().trim()
      );
      if (matchedUser) {
        currentItem.supervisorEmail = matchedUser.email;
      } else if (currentItem.isCustomSupervisor1) {
        currentItem.supervisorEmail = '';
      }
    } else if (field === 'supervisor2Email') {
      if (value === '__CUSTOM__') {
        currentItem.isCustomSupervisor2 = true;
        currentItem.supervisor2Email = '';
        currentItem.hasSecondSupervisor = true;
      } else {
        const sup2 = users.find(u => u.email === value);
        currentItem.isCustomSupervisor2 = false;
        currentItem.supervisor2Email = value;
        currentItem.supervisor2Name = sup2?.username || (value ? currentItem.supervisor2Name : '');
        if (value) currentItem.hasSecondSupervisor = true;
      }
    } else if (field === 'supervisor2Name') {
      currentItem.supervisor2Name = value;
      currentItem.hasSecondSupervisor = true;
      const matchedUser2 = users.find(
        u => (u.username || '').toLowerCase().trim() === String(value || '').toLowerCase().trim()
      );
      if (matchedUser2) {
        currentItem.supervisor2Email = matchedUser2.email;
      } else if (currentItem.isCustomSupervisor2) {
        currentItem.supervisor2Email = '';
      }
    } else if (field === 'hasSecondSupervisor') {
      currentItem.hasSecondSupervisor = Boolean(value);
      if (!value) {
        currentItem.supervisor2Email = '';
        currentItem.supervisor2Name = '';
        currentItem.isCustomSupervisor2 = false;
      }
    } else {
      currentItem[field] = value;
    }

    currentList[rowIdx] = currentItem;

    const summaryRoom = currentList.map(r => r.roomName).filter(Boolean).join(', ');
    const summarySupEmail =
      currentList.find(r => r.supervisorEmail || r.supervisor2Email)?.supervisorEmail ||
      currentList.find(r => r.supervisor2Email)?.supervisor2Email ||
      '';
    const summarySupName =
      currentList.map(r => formatRoomSupervisorDisplayName(r)).filter(Boolean)[0] || '';

    const updatedSessions = [...day.sessions];
    updatedSessions[sIdx] = {
      ...session,
      roomSupervisors: currentList,
      roomName: summaryRoom || session.roomName,
      supervisorEmail: summarySupEmail || session.supervisorEmail,
      supervisorName: summarySupName || session.supervisorName
    };

    // Optimistic: instantly reflect in UI & cache
    setMasterPlan(prev => {
      const next = prev.map(d => d.id === dayId ? { ...d, sessions: updatedSessions } : d);
      broadcastMasterPlanUpdate(next);
      return next;
    });
    safeUpdateMasterPlanDay(dayId, { sessions: updatedSessions });
  };

