  const handleAutoFillAllRooms = async (dayId: string, sIdx: number, customCount: number = 30) => {
    if (!canEditSchedule) return;
    const day = masterPlan.find(d => d.id === dayId);
    if (!day) return;
    const session = day.sessions?.[sIdx];
    if (!session) return;

    let sourceRooms = rooms.map(r => r.name);
    if (sourceRooms.length < customCount) {
      sourceRooms = Array.from({ length: customCount }, (_, i) => rooms[i]?.name || `Ruang ${i + 1}`);
    } else if (sourceRooms.length > customCount) {
      sourceRooms = sourceRooms.slice(0, customCount);
    }

    const existingMap = new Map((session.roomSupervisors || []).map((rs: any) => [rs.roomName, rs]));

    const newList = sourceRooms.map((rName, idx) => {
      const existing: any = existingMap.get(rName);
      return {
        id: existing?.id || `rs-${Date.now()}-${idx}`,
        roomName: rName,
        supervisorEmail: existing?.supervisorEmail || '',
        supervisorName: existing?.supervisorName || ''
      };
    });

    const summaryRoom = newList.map(r => r.roomName).filter(Boolean).join(', ');
    const summarySupEmail = newList.find(r => r.supervisorEmail)?.supervisorEmail || '';
    const summarySupName = newList.find(r => r.supervisorName)?.supervisorName || '';

    const updatedSessions = [...day.sessions];
    updatedSessions[sIdx] = {
      ...session,
      roomSupervisors: newList,
      roomName: summaryRoom,
      supervisorEmail: summarySupEmail,
      supervisorName: summarySupName
    };

    // Optimistic: instantly reflect in UI
    setMasterPlan(prev => {
      const next = prev.map(d => d.id === dayId ? { ...d, sessions: updatedSessions } : d);
      broadcastMasterPlanUpdate(next);
      return next;
    });
    safeUpdateMasterPlanDay(dayId, { sessions: updatedSessions });
  };

