  const handleBulkDelete = () => {
    if (selectedUserIds.length === 0) return;
    setIsBulkDelete(true);
    setShowDeleteModal(true);
  };

  const confirmDelete = async () => {
    try {
      if (isBulkDelete) {
        // Protect super admin and logged-in user from deletion
        const safeIdsToDelete = selectedUserIds.filter(id => {
          const target = users.find(u => u.id === id);
          return !isSuperAdminEmail(target?.email) && id !== userProfile?.uid;
        });

        if (safeIdsToDelete.length === 0) {
          alert('Tidak ada user yang dapat dihapus. Akun Super Admin atau akun yang sedang aktif dilindungi.');
          setShowDeleteModal(false);
          setIsBulkDelete(false);
          return;
        }

        const deletedSet = new Set(safeIdsToDelete);
        const nextUsersList = users.filter(u => !deletedSet.has(u.id));
        const deletedCount = safeIdsToDelete.length;

        setUsers(nextUsersList);
        setSelectedUserIds([]);
        setShowDeleteModal(false);
        setUserToDelete(null);
        setIsBulkDelete(false);
        showToast(`${deletedCount} akun berhasil dihapus & dicabut akses loginnya.`, 'success');

        setTimeout(async () => {
          safeIdsToDelete.forEach(id => removeUpdatedUserLocally(id));
          try {
            localStorage.setItem('cached_dashboard_users', JSON.stringify(nextUsersList));
            localStorage.setItem('cached_roster_catalog', JSON.stringify(nextUsersList));
          } catch (e) {}

          await Promise.allSettled([
            ...safeIdsToDelete.map(id => withFirestoreTimeout(deleteDoc(doc(db, 'users', id)), 2500)),
            ...safeIdsToDelete.map(id => deleteUserFromSpreadsheet(id, appSettings?.spreadsheetWebAppUrl)),
            syncRosterCatalogToFirestore(nextUsersList, false),
          ]);
        }, 0);
      } else if (userToDelete) {
        if (isSuperAdminEmail(userToDelete.email) || userToDelete.id === userProfile?.uid) {
          alert('Akun Super Admin atau akun yang sedang aktif tidak dapat dihapus.');
          setShowDeleteModal(false);
          setUserToDelete(null);
          return;
        }
        const targetDeleteId = userToDelete.id;
        const targetDeleteName = userToDelete.username;
        const nextUsersList = users.filter(u => u.id !== targetDeleteId);

        setUsers(nextUsersList);
        setShowDeleteModal(false);
        setUserToDelete(null);
        setIsBulkDelete(false);
        showToast(`Akun ${targetDeleteName} berhasil dihapus & tidak dapat login lagi.`, 'success');

        setTimeout(async () => {
          removeUpdatedUserLocally(targetDeleteId);
          try {
            localStorage.setItem('cached_dashboard_users', JSON.stringify(nextUsersList));
            localStorage.setItem('cached_roster_catalog', JSON.stringify(nextUsersList));
          } catch (e) {}

          await Promise.allSettled([
            withFirestoreTimeout(deleteDoc(doc(db, 'users', targetDeleteId)), 2500),
            deleteUserFromSpreadsheet(targetDeleteId, appSettings?.spreadsheetWebAppUrl),
            syncRosterCatalogToFirestore(nextUsersList, false),
          ]);
        }, 0);
      }
    } catch (error) {
      console.error("Error deleting user:", error);
      alert('Gagal menghapus user. Pastikan Anda memiliki izin.');
      setShowDeleteModal(false);
      setUserToDelete(null);
      setIsBulkDelete(false);
    }
  };

  const toggleSelectAll = () => {
    const visibleUsers = getFilteredUsers();
    const visibleIds = visibleUsers.map(u => u.id);
    
    // Check if all visible users are currently selected
    const allVisibleSelected = visibleIds.length > 0 && visibleIds.every(id => selectedUserIds.includes(id));
    
    if (allVisibleSelected) {
      // Uncheck only visible users from current active filter/tab
      setSelectedUserIds(prev => prev.filter(id => !visibleIds.includes(id)));
    } else {
      // Select ONLY currently visible users on the active tab, protecting Super Admin and self
      const safeIds = visibleUsers
        .filter(u => !isSuperAdminEmail(u.email) && u.id !== userProfile?.uid)
        .map(u => u.id);
      setSelectedUserIds(safeIds);
    }
  };

  const toggleSelectUser = (userId: string) => {
    setSelectedUserIds(prev => 
      prev.includes(userId) 
        ? prev.filter(id => id !== userId) 
        : [...prev, userId]
    );
  };

  useEffect(() => {
    const timer = setInterval(() => {
      setCooldowns(prev => {
        const next = { ...prev };
        let changed = false;
        const now = Date.now();
        
        Object.keys(next).forEach(email => {
          if (next[email] > 0) {
            next[email] -= 1;
            changed = true;
          } else {
            delete next[email];
            changed = true;
          }
        });

        if (changed) {
          const storageObj: Record<string, number> = {};
          Object.keys(next).forEach(email => {
            storageObj[email] = now + (next[email] * 1000);
          });
          localStorage.setItem('reset_cooldowns', JSON.stringify(storageObj));
        }
        
        return changed ? next : prev;
      });
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  const handleResetUserPassword = async (email: string) => {
    if (resettingEmail || cooldowns[email]) return;
    setResettingEmail(email);
    try {
      await resetPassword(email);
      const newCooldown = 60;
      setCooldowns(prev => {
        const next = { ...prev, [email]: newCooldown };
        const storageObj: Record<string, number> = {};
        const now = Date.now();
        Object.keys(next).forEach(e => {
          storageObj[e] = now + (next[e] * 1000);
        });
        localStorage.setItem('reset_cooldowns', JSON.stringify(storageObj));
        return next;
      });
      alert(`Email reset password telah dikirim ke ${email}. Silakan cek kotak masuk atau folder spam.`);
    } catch (error: any) {
      console.error("Reset password error:", error);
      if (error.code === 'auth/too-many-requests' || error.message?.includes('too-many-requests')) {
        const longCooldown = 300;
        setCooldowns(prev => {
          const next = { ...prev, [email]: longCooldown };
          const storageObj: Record<string, number> = {};
          const now = Date.now();
          Object.keys(next).forEach(e => {
            storageObj[e] = now + (next[e] * 1000);
          });
          localStorage.setItem('reset_cooldowns', JSON.stringify(storageObj));
          return next;
        });
        alert('Terlalu banyak permintaan reset password untuk email ini. Firebase membatasi pengiriman email untuk keamanan. Silakan tunggu sekitar 5 menit sebelum mencoba lagi.');
      } else {
        alert('Gagal mengirim email reset password: ' + (error.message || 'Terjadi kesalahan.'));
      }
    } finally {
      setResettingEmail(null);
    }
  };

