  const downloadExcelWorkbook = (wb: XLSX.WorkBook, fileName: string): boolean => {
    try {
      const lower = fileName.toLowerCase();
      const isBiff8Xls = lower.endsWith('.xls') && !lower.endsWith('.xlsx');
      const bookType = isBiff8Xls ? 'biff8' : 'xlsx';
      const mimeType = isBiff8Xls
        ? 'application/vnd.ms-excel'
        : 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
      const wbout = XLSX.write(wb, { bookType, type: 'array' });
      const blob = new Blob([wbout], { type: mimeType });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', fileName);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      setTimeout(() => URL.revokeObjectURL(url), 2000);
      return true;
    } catch (err: any) {
      console.error('Error downloading Excel file:', err);
      showToast('Gagal mengunduh file Excel: ' + (err?.message || 'Terjadi kesalahan.'), 'error');
      return false;
    }
  };

