                              const email = e.target.value;
                              const supervisor = users.find(u => u.email === email);
                              if (!supervisor) return;

                              const startTime = Timestamp.fromDate(new Date(`${selectedSessionForScheduling.date}T${selectedSessionForScheduling.startTime}`));
                              const subject = subjects.find(s => s.id === selectedSessionForScheduling.subjectId);
                              const subjectName = subject?.name || '';
                              const subjectId = subject?.id || '';

