                      (document.getElementById('edit-as-class') as HTMLSelectElement).value = '';
                      (document.getElementById('edit-as-room') as HTMLSelectElement).value = '';
                      (document.getElementById('edit-as-supervisor') as HTMLSelectElement).value = '';
