      {/* Modal Pusat Manajemen Cache Per-Role & Backup/Restore (Siap Remix) */}
      <DataCacheAndBackupCenter
        role={normalizedRole}
        isActualAdmin={isActualAdmin}
        appSettings={appSettings}
        users={users}
        classrooms={classrooms}
        rooms={rooms}
        subjects={subjects}
        exams={exams}
        schedules={schedules}
        masterPlan={masterPlan}
        tokens={tokens}
        studentTokens={studentTokens}
        violations={violations}
        attendanceAbsenceNotes={attendanceAbsenceNotes}
        onUpdateStateAfterRestore={(restored) => {
          if (restored.appSettings) setAppSettings((prev: any) => ({ ...prev, ...restored.appSettings }));
          if (restored.users) setUsers(restored.users);
          if (restored.classrooms) setClassrooms(restored.classrooms);
          if (restored.rooms) setRooms(restored.rooms);
          if (restored.subjects) setSubjects(restored.subjects);
          if (restored.exams) setExams(restored.exams);
          if (restored.schedules) setSchedules(restored.schedules);
          if (restored.masterPlan) setMasterPlan(restored.masterPlan);
          if (restored.tokens) {
            setTokens(restored.tokens);
            setStudentTokens(restored.tokens);
          }
          if (restored.violations) setViolations(restored.violations);
          if (restored.attendanceAbsenceNotes) setAttendanceAbsenceNotes(restored.attendanceAbsenceNotes);
        }}
        onClearLocalTransactionState={() => {
          setViolations([]);
          setStudentTokens([]);
          if (!isAdmin) setTokens([]);
        }}
        onRefreshData={() => {
          const targetUid = isStudent
            ? effectiveStudentUid
            : (user?.uid || userProfile?.uid || userProfile?.id || auth.currentUser?.uid || '');
          const targetName = isStudent
            ? effectiveStudentName
            : (userProfile?.username || userProfile?.name || user?.displayName || '');
          syncStudentExamAndViolationData(targetUid, targetName, true);
        }}
        showToast={showToast}
        mode="modal"
        isOpen={showCacheAndBackupModal}
        onClose={() => setShowCacheAndBackupModal(false)}
      />

